/* From Uiverse.io by aadium - Tags: card, code, syntax */
.__UIV_SCOPE__ .card {
  width: 250px;
  height: 300px;
  background: #15001f;
  border: 1px solid #c042ff;
  font-size: 14px;
  font-family: monospace;
  overflow: auto;
}

.__UIV_SCOPE__ .titlebar {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  font-size: 21px;
  font-weight: 450;
  background-color: #2e0043;
  width: 100%;
  text-align: right;
}

.__UIV_SCOPE__ .card button {
  width: 40px;
  height: 35px;
  margin-left: -5px;
  border: 0;
  outline: 0;
  background: transparent;
  transition: 0.2s;
}

.__UIV_SCOPE__ button svg path, 
.__UIV_SCOPE__ button svg rect, 
.__UIV_SCOPE__ button svg polygon {
  fill: #ffffff;
}

.__UIV_SCOPE__ button svg {
  width: 10px;
  height: 10px;
}

.__UIV_SCOPE__ .close:hover {
  background-color: #e81123;
}

.__UIV_SCOPE__ .maximize:hover {
  background-color: #c042ff2e;
}

.__UIV_SCOPE__ .minimize:hover {
  background-color: #c042ff2e;
}

.__UIV_SCOPE__ #pre {
  overflow: auto;
  width: 100%;
  padding: 10px;
  height: auto;
  color: #bafff8;
}

.__UIV_SCOPE__ .curlies {
  color: #ff0000;
}

.__UIV_SCOPE__ .sc {
  color: #e600ff;
}

.__UIV_SCOPE__ .rounds {
  color: #ffffff;
}

.__UIV_SCOPE__ .operator {
  color: #ffff00;
}

.__UIV_SCOPE__ .s1 {
  color: #22ff00;
}

.__UIV_SCOPE__ .s2 {
  color: #4281ff;
}

.__UIV_SCOPE__ .s3 {
  color: #ff4284;
}

.__UIV_SCOPE__ .s4 {
  color: #ffae00;
}

.__UIV_SCOPE__ .s5 {
  color: #ffffff;
}

.__UIV_SCOPE__ .s6 {
  color: #ffff00;
}
